class UnionFind(n: Int) {
    private val parent = IntArray(n) { it }          // every node starts as its own root
    private val size = IntArray(n) { 1 }
    var components = n
        private set

    fun find(x: Int): Int {
        if (parent[x] != x) {
            parent[x] = find(parent[x])              // path compression
        }
        return parent[x]
    }

    fun union(a: Int, b: Int): Boolean {
        var rootA = find(a)
        var rootB = find(b)
        if (rootA == rootB) return false             // already in the same group
        if (size[rootA] < size[rootB]) {             // attach the smaller tree under the larger
            val tmp = rootA
            rootA = rootB
            rootB = tmp
        }
        parent[rootB] = rootA
        size[rootA] += size[rootB]
        components--
        return true
    }

    fun connected(a: Int, b: Int): Boolean = find(a) == find(b)

    fun sizeOf(x: Int): Int = size[find(x)]
}
// find / union: O(α(n)) amortized   Space: O(n)

fun find(x: Int): Int {
    var cur = x
    while (parent[cur] != cur) {
        parent[cur] = parent[parent[cur]]            // skip one level on the way up
        cur = parent[cur]
    }
    return cur
}
// Same complexity, no recursion: safe for very large inputs

class MapUnionFind<T> {
    private val parent = HashMap<T, T>()
    private val size = HashMap<T, Int>()

    private fun add(x: T) {
        if (x !in parent) {
            parent[x] = x
            size[x] = 1
        }
    }

    fun find(x: T): T {
        add(x)
        var root = x
        while (parent[root] != root) root = parent[root]!!
        var cur = x
        while (cur != root) {                        // compress the path
            val next = parent[cur]!!
            parent[cur] = root
            cur = next
        }
        return root
    }

    fun union(a: T, b: T): Boolean {
        var rootA = find(a)
        var rootB = find(b)
        if (rootA == rootB) return false
        if (size[rootA]!! < size[rootB]!!) {
            val tmp = rootA
            rootA = rootB
            rootB = tmp
        }
        parent[rootB] = rootA
        size[rootA] = size[rootA]!! + size[rootB]!!
        return true
    }
}
// Use for strings, pairs or sparse IDs where an array index is not available

fun countComponents(n: Int, edges: Array<IntArray>): Int {
    val uf = UnionFind(n)
    for ((a, b) in edges) uf.union(a, b)
    return uf.components
}
// Time: O((V + E) * α(V))   Space: O(V)

fun findCircleNum(isConnected: Array<IntArray>): Int {
    val n = isConnected.size
    val uf = UnionFind(n)
    for (i in 0 until n) {
        for (j in i + 1 until n) {
            if (isConnected[i][j] == 1) uf.union(i, j)
        }
    }
    return uf.components
}
// Time: O(n² * α(n))   Space: O(n)

fun findRedundantConnection(edges: Array<IntArray>): IntArray {
    val uf = UnionFind(edges.size + 1)               // nodes are 1-indexed
    for (edge in edges) {
        if (!uf.union(edge[0], edge[1])) {           // endpoints already connected: this edge closes a cycle
            return edge
        }
    }
    return intArrayOf()
}
// Time: O(n * α(n))   Space: O(n)

fun validTree(n: Int, edges: Array<IntArray>): Boolean {
    if (edges.size != n - 1) return false            // a tree has exactly n - 1 edges
    val uf = UnionFind(n)
    for ((a, b) in edges) {
        if (!uf.union(a, b)) return false            // a cycle means it is not a tree
    }
    return true
}
// Time: O(n * α(n))   Space: O(n)

fun accountsMerge(accounts: List<List<String>>): List<List<String>> {
    val uf = UnionFind(accounts.size)
    val emailOwner = HashMap<String, Int>()          // email -> first account that had it

    for ((i, account) in accounts.withIndex()) {
        for (j in 1 until account.size) {
            val email = account[j]
            val owner = emailOwner[email]
            if (owner == null) emailOwner[email] = i
            else uf.union(owner, i)                  // shared email: merge the two accounts
        }
    }

    val groups = HashMap<Int, MutableList<String>>()
    for ((email, owner) in emailOwner) {
        groups.getOrPut(uf.find(owner)) { mutableListOf() }.add(email)
    }

    val result = mutableListOf<List<String>>()
    for ((root, emails) in groups) {
        emails.sort()
        result.add(listOf(accounts[root][0]) + emails)
    }
    return result
}
// Time: O(N * L * α + E log E)   Space: O(N * L)

fun numIslands2(m: Int, n: Int, positions: Array<IntArray>): List<Int> {
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    val uf = UnionFind(m * n)
    val isLand = BooleanArray(m * n)
    var islands = 0
    val result = mutableListOf<Int>()

    for ((r, c) in positions) {
        val id = r * n + c
        if (!isLand[id]) {
            isLand[id] = true
            islands++                                // a new island
            for ((dr, dc) in dirs) {
                val nr = r + dr
                val nc = c + dc
                if (nr in 0 until m && nc in 0 until n && isLand[nr * n + nc]) {
                    if (uf.union(id, nr * n + nc)) islands--   // merging two islands removes one
                }
            }
        }
        result.add(islands)
    }
    return result
}
// Time: O(k * α(m * n))   Space: O(m * n)
// DFS would redo the whole grid after each addition: O(k * m * n)

fun removeStones(stones: Array<IntArray>): Int {
    val uf = UnionFind(20002)
    for ((r, c) in stones) {
        uf.union(r, c + 10001)                       // row r and column c become connected
    }
    val roots = HashSet<Int>()
    for ((r, _) in stones) roots.add(uf.find(r))     // distinct groups
    return stones.size - roots.size                  // keep one stone per group
}
// Time: O(n * α)   Space: O(20002)
// Stones sharing a row or column are in one group, and each group can shrink to one stone

fun equationsPossible(equations: Array<String>): Boolean {
    val uf = UnionFind(26)
    for (e in equations) {
        if (e[1] == '=') uf.union(e[0] - 'a', e[3] - 'a')     // first apply all equalities
    }
    for (e in equations) {
        if (e[1] == '!' && uf.connected(e[0] - 'a', e[3] - 'a')) return false
    }
    return true
}
// Time: O(n * α)   Space: O(1)

fun longestConsecutive(nums: IntArray): Int {
    if (nums.isEmpty()) return 0
    val uf = UnionFind(nums.size)
    val index = HashMap<Int, Int>()                  // value -> index in nums
    for ((i, x) in nums.withIndex()) {
        if (x in index) continue                     // skip duplicates
        index[x] = i
        index[x - 1]?.let { uf.union(i, it) }
        index[x + 1]?.let { uf.union(i, it) }
    }
    var best = 1
    for (i in nums.indices) best = maxOf(best, uf.sizeOf(i))
    return best
}
// Time: O(n * α(n))   Space: O(n)
// The HashSet start-of-sequence method is simpler, this shows the DSU idea

fun smallestStringWithSwaps(s: String, pairs: List<List<Int>>): String {
    val uf = UnionFind(s.length)
    for ((a, b) in pairs) uf.union(a, b)

    val groups = HashMap<Int, MutableList<Int>>()
    for (i in s.indices) {
        groups.getOrPut(uf.find(i)) { mutableListOf() }.add(i)   // indices in ascending order
    }

    val result = CharArray(s.length)
    for (indices in groups.values) {
        val chars = indices.map { s[it] }.sorted()               // sort letters of the group
        for ((k, idx) in indices.withIndex()) {
            result[idx] = chars[k]                               // smallest letters to earliest slots
        }
    }
    return String(result)
}
// Time: O(n log n)   Space: O(n)
// Swaps inside a connected group can reach any permutation of that group

class WeightedUnionFind {
    private val parent = HashMap<String, String>()
    private val weight = HashMap<String, Double>()       // value of node / value of its parent

    fun find(x: String): String {
        if (x !in parent) {
            parent[x] = x
            weight[x] = 1.0
        }
        if (parent[x] != x) {
            val p = parent[x]!!
            val root = find(p)
            weight[x] = weight[x]!! * weight[p]!!        // now x / root
            parent[x] = root
        }
        return parent[x]!!
    }

    fun union(a: String, b: String, value: Double) {     // a / b = value
        val rootA = find(a)
        val rootB = find(b)
        if (rootA != rootB) {
            parent[rootA] = rootB
            weight[rootA] = value * weight[b]!! / weight[a]!!
        }
    }

    fun query(a: String, b: String): Double {
        if (a !in parent || b !in parent) return -1.0
        if (find(a) != find(b)) return -1.0
        return weight[a]!! / weight[b]!!
    }
}

fun calcEquation(
    equations: List<List<String>>,
    values: DoubleArray,
    queries: List<List<String>>
): DoubleArray {
    val uf = WeightedUnionFind()
    for ((i, eq) in equations.withIndex()) uf.union(eq[0], eq[1], values[i])
    return DoubleArray(queries.size) { uf.query(queries[it][0], queries[it][1]) }
}
// Time: O((E + Q) * α)   Space: O(V)
// Each node stores a ratio to its parent, so the path product gives the ratio to the root

import kotlin.math.abs

fun minCostConnectPoints(points: Array<IntArray>): Int {
    val n = points.size
    val edges = ArrayList<IntArray>()
    for (i in 0 until n) {
        for (j in i + 1 until n) {
            val dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            edges.add(intArrayOf(dist, i, j))
        }
    }
    edges.sortBy { it[0] }                           // cheapest edges first

    val uf = UnionFind(n)
    var total = 0
    var used = 0
    for ((dist, a, b) in edges) {
        if (uf.union(a, b)) {                        // take the edge only if it joins two groups
            total += dist
            used++
            if (used == n - 1) break
        }
    }
    return total
}
// Time: O(E log E) with E = n²   Space: O(E)

fun makeConnected(n: Int, connections: Array<IntArray>): Int {
    if (connections.size < n - 1) return -1          // not enough cables to link every computer
    val uf = UnionFind(n)
    for ((a, b) in connections) uf.union(a, b)
    return uf.components - 1                         // one move connects two components
}
// Time: O((n + E) * α(n))   Space: O(n)
